import { createRoot } from 'react-dom/client';
import { Toaster } from 'sonner';
import App from './App';
import './styles.css';

const root = createRoot(document.getElementById('root')!);
root.render(<><App /><Toaster richColors position="top-right" /></>);

html, body, #root { height: 100%; }
body { margin: 0; background: #fafafa; color: #0a0a0a;
       font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif;
       -webkit-font-smoothing: antialiased; }

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import { useEffect, useState } from 'react';
import { Check, Trash2, Plus } from 'lucide-react';

type Todo = { id: string; text: string; done: boolean };

const STORAGE_KEY = 'app.todos.v1';

function load(): Todo[] {
  try { return JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]'); } catch { return []; }
}

export default function App() {
  const [todos, setTodos] = useState<Todo[]>(() => load());
  const [draft, setDraft] = useState('');
  const [filter, setFilter] = useState<'all' | 'active' | 'done'>('all');

  useEffect(() => { localStorage.setItem(STORAGE_KEY, JSON.stringify(todos)); }, [todos]);

  function add() {
    const text = draft.trim();
    if (!text) return;
    setTodos((t) => [{ id: crypto.randomUUID(), text, done: false }, ...t]);
    setDraft('');
  }

  function toggle(id: string) {
    setTodos((t) => t.map((x) => (x.id === id ? { ...x, done: !x.done } : x)));
  }

  function remove(id: string) {
    setTodos((t) => t.filter((x) => x.id !== id));
  }

  function clearDone() {
    setTodos((t) => t.filter((x) => !x.done));
  }

  const filtered = todos.filter((t) =>
    filter === 'all' ? true : filter === 'active' ? !t.done : t.done,
  );
  const remaining = todos.filter((t) => !t.done).length;

  return (
    <div className="min-h-screen flex items-start justify-center bg-neutral-50 p-6">
      <div className="w-full max-w-xl mt-12 rounded-2xl bg-white shadow-sm ring-1 ring-neutral-200 p-6">
        <h1 className="text-2xl font-semibold text-neutral-900 mb-4">Tasks</h1>

        <form
          onSubmit={(e) => { e.preventDefault(); add(); }}
          className="flex gap-2 mb-4"
        >
          <input
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            placeholder="What needs doing?"
            className="flex-1 rounded-lg border border-neutral-200 bg-white px-3 py-2 text-sm text-neutral-900 placeholder:text-neutral-400 focus:outline-none focus:ring-2 focus:ring-neutral-900"
          />
          <button
            type="submit"
            className="rounded-lg bg-neutral-900 px-4 py-2 text-sm font-medium text-white hover:bg-neutral-800 inline-flex items-center gap-1"
          >
            <Plus className="h-4 w-4" /> Add
          </button>
        </form>

        <div className="flex items-center justify-between mb-3 text-sm text-neutral-500">
          <div className="flex gap-1">
            {(['all', 'active', 'done'] as const).map((f) => (
              <button
                key={f}
                onClick={() => setFilter(f)}
                className={`px-2 py-1 rounded ${filter === f ? 'bg-neutral-900 text-white' : 'hover:bg-neutral-100'}`}
              >{f}</button>
            ))}
          </div>
          <span>{remaining} left</span>
        </div>

        <ul className="space-y-1">
          {filtered.length === 0 && (
            <li className="text-sm text-neutral-400 py-6 text-center">Nothing here yet.</li>
          )}
          {filtered.map((t) => (
            <li key={t.id} className="flex items-center gap-3 py-2 px-2 rounded hover:bg-neutral-50 group">
              <button
                onClick={() => toggle(t.id)}
                aria-label={t.done ? 'Mark active' : 'Mark done'}
                className={`h-5 w-5 rounded border flex items-center justify-center transition ${
                  t.done
                    ? 'bg-neutral-900 border-neutral-900 text-white'
                    : 'border-neutral-300 hover:border-neutral-500'
                }`}
              >
                {t.done && <Check className="h-3 w-3" />}
              </button>
              <span className={`flex-1 text-sm ${t.done ? 'line-through text-neutral-400' : 'text-neutral-900'}`}>
                {t.text}
              </span>
              <button
                onClick={() => remove(t.id)}
                aria-label="Delete"
                className="text-neutral-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition"
              >
                <Trash2 className="h-4 w-4" />
              </button>
            </li>
          ))}
        </ul>

        {todos.some((t) => t.done) && (
          <button
            onClick={clearDone}
            className="mt-4 text-xs text-neutral-500 hover:text-neutral-900"
          >Clear completed</button>
        )}
      </div>
    </div>
  );
}
